typedef unsigned long long uint64;

struct string_buf
{
  uint64* data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;
};

class stringx
{
public:
  char* chars;
  string_buf* my_buf;

  stringx();
  stringx(const char*, int = -1);
  ~stringx();
};

inline bool operator==(const stringx& lhs, const stringx& rhs)
{
  if (lhs.my_buf->char_length != rhs.my_buf->char_length)
    return false;
  for (int i = 0; i < lhs.my_buf->char_length; ++i)
    if (lhs.my_buf->data[i] != rhs.my_buf->data[i])
      return false;
  return true;
}

inline bool operator!=(const stringx& lhs, const stringx& rhs)
{
  return !(lhs == rhs);
}

class chunk_file;
class terrain;

void serial_in(chunk_file&, stringx*);
extern const stringx chunkend_label;

class entity
{
public:
  virtual bool parse_instance(const stringx&, chunk_file&);
  virtual void compute_sector(terrain&, bool = false);
};

class beam : public entity
{
public:
  virtual bool parse_instance(const stringx&, chunk_file&);
  virtual bool handle_enx_chunk(chunk_file&, stringx&);
};

class world_dynamics_system
{
  char pad[236];
  terrain* the_terrain;

public:
  terrain& get_the_terrain() { return *the_terrain; }
};

extern world_dynamics_system* g_world_ptr;

bool beam::parse_instance( const stringx& pcf, chunk_file& fs )
{
  if ( pcf == stringx("beam:") )
  {
    stringx label;
    for ( serial_in(fs,&label); label!=chunkend_label; serial_in(fs,&label) )
      handle_enx_chunk( fs, label );

    compute_sector(g_world_ptr->get_the_terrain());

    return true;
  }

  return (entity::parse_instance( pcf, fs ) );
}
